// A still copy of the screen on the glass, with every scroll position, so the dissolve starts from exactly what the person was looking at.
function takeScreenPicture(el) {
  if (!el) return null;
  const copy = el.cloneNode(true);
  copy.style.animation = "none";
  const live = el.querySelectorAll("*");
  const tops = [];
  live.forEach((n, i) => { if (n.scrollTop) tops.push([i, n.scrollTop]); });
  return { copy, top: el.scrollTop, tops };
}
function showScreenPicture(host, pic) {
  if (!host || host.firstChild) return;
  host.appendChild(pic.copy);
  pic.copy.scrollTop = pic.top;
  const all = pic.copy.querySelectorAll("*");
  pic.tops.forEach(([i, t]) => { if (all[i]) all[i].scrollTop = t; });
}
