var PROPER_MINOR = new Set(["a", "an", "and", "as", "at", "but", "by", "for", "from", "in", "nor", "of", "on", "or", "per", "the", "to", "up", "vs", "with"]);
// Phone numbers shown the one way everywhere. Mobiles (04), 1300 and 1800 numbers read xxxx xxx xxx. Any other ten digit number reads xx xxxx xxxx. Six digit 13 numbers read 13 xx xx.
// Anything else (a short local number, text) is shown as it was typed. The Worker saves numbers in the same style (see normPhone there).
function fmtPhone(v) {
  const raw = String(v === null || v === undefined ? "" : v).trim();
  if (!raw) return raw;
  let d = raw.replace(/[^0-9+]/g, "");
  if (/^\+61\d{9}$/.test(d)) d = `0${d.slice(3)}`;
  else if (/^61\d{9}$/.test(d)) d = `0${d.slice(2)}`;
  if (/^13\d{4}$/.test(d)) return `${d.slice(0, 2)} ${d.slice(2, 4)} ${d.slice(4)}`;
  if (!/^\d{10}$/.test(d)) return raw;
  if (d.startsWith("04") || d.startsWith("1300") || d.startsWith("1800")) return `${d.slice(0, 4)} ${d.slice(4, 7)} ${d.slice(7)}`;
  return `${d.slice(0, 2)} ${d.slice(2, 6)} ${d.slice(6)}`;
}
function properCase(text) {
  return typeof text === "string" ? text.replace(/(^|\s)([a-z])([A-Za-z]*)/g, (m, space, letter, rest, offset) => (offset > 0 && PROPER_MINOR.has(letter + rest) ? m : space + letter.toUpperCase() + rest)) : text;
}
