// Fetches one payslip for the screen and the PDF.
async function loadPayslip(id, employeeId) {
  if (PREVIEW_BYPASS_AUTH) return PAYSLIP_SAMPLE;
  const token = await getApiToken();
  const res = await fetch(`${FLEET_API_URL}${employeeId ? `/api/dfp/payslips/for/${encodeURIComponent(employeeId)}/${encodeURIComponent(id)}` : `/api/xero/payslips/${encodeURIComponent(id)}`}`, { headers: { Authorization: `Bearer ${token}` } });
  if (!res.ok) throw new Error(xeroFail(res, await res.text()));
  const slip = (await res.json()).payslip;
  let logo = "";
  try {
    const lr = await fetch(`${FLEET_API_URL}/api/files/payslip-logo`, { headers: { Authorization: `Bearer ${token}` } });
    const lj = lr.ok ? await lr.json() : {};
    if (lj.found && /^data:image\/(png|jpeg);base64,/.test(lj.data || "")) logo = lj.data;
  } catch (e) { /* the built in logo is used */ }
  return { ...slip, logo, employer: { name: COMPANY.legalName, abn: COMPANY.abn, address: COMPANY.address } };
}
// Hands the PDF to the phone's share sheet (Save to Files), or downloads it where sharing files is not offered.
async function savePayslipPdf(blob, name) {
  try {
    const file = new File([blob], name, { type: "application/pdf" });
    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      await navigator.share({ files: [file], title: name });
      return "shared";
    }
  } catch (e) {
    if (e && e.name === "AbortError") return "cancelled";
  }
  const href = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = href;
  a.download = name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(href), 60000);
  return "saved";
}
