  const nm = /Voicemail name:\s*([A-Za-z][A-Za-z &]*?)\s*(?:Caller ID|Kind Regards|$)/i.exec(text);
  const who = /^\s*(?:re:\s*|fw:\s*|fwd:\s*)?voicemail from\s+(.+?)\s*(?:-\s*\d+:\d+.*)?$/i.exec(String(subject || ""));
