// The invoice pickup history, grouped by Melbourne day, newest day first.
function invDays(rows) {
  const out = [];
  for (const r of rows) {
    const d = new Date(String(r.at).replace(" ", "T") + "Z");
    const key = d.toLocaleDateString("en-CA", { timeZone: "Australia/Melbourne" });
    let g = out.find((x) => x.key === key);
    if (!g) { g = { key, weekday: d.toLocaleDateString("en-AU", { timeZone: "Australia/Melbourne", weekday: "long" }), date: d.toLocaleDateString("en-AU", { timeZone: "Australia/Melbourne", day: "numeric", month: "long" }), rows: [] }; out.push(g); }
    g.rows.push(r);
  }
  for (const g of out) g.rows.sort((a, b) => String(a.supplier).localeCompare(String(b.supplier), void 0, { sensitivity: "base", numeric: true }) || String(a.number).localeCompare(String(b.number), void 0, { numeric: true }));
  return out;
}
