// A file from AroFlo's document store, fetched through the Worker as a blob.
async function arofloFileBlob(path, d, job) {
  const token = await getApiToken();
  const res = await fetch(`${FLEET_API_URL}/api/aroflo/file?path=${encodeURIComponent(path)}${d && d.id ? `&doc=${encodeURIComponent(d.id)}` : ""}${job && job.id ? `&job=${encodeURIComponent(job.id)}&coll=${encodeURIComponent(job.collection || "")}` : ""}`, { headers: { Authorization: `Bearer ${token}` } });
  if (!res.ok) {
    let why = "";
    try { why = ((await res.json()).tried || []).join(", "); } catch (e) { why = ""; }
    throw new Error(`AroFlo would not give that file${why ? ` (${why})` : ""}`);
  }
  return res.blob();
}
